WITH unpacked AS (SELECT id, plan, effective_from, tier_limits, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers WHERE effective_from BETWEEN '2023-08-01' AND '2023-09-01') SELECT plan, CASE WHEN lowest_price >= 28 THEN 'PREMIUM' ELSE 'STANDARD' END AS lowest_price_tier, APPROX_PERCENTILE(lowest_price, 0.5) AS lowest_price_p50, ROUND(SUM(lowest_price) / NULLIF(COUNT(CASE WHEN plan = 'starter' THEN 1 END), 0), 2) AS lowest_price_per_starter, ROUND(SUM(lowest_price) / NULLIF(COUNT(CASE WHEN plan = 'pro' THEN 1 END), 0), 2) AS lowest_price_per_pro FROM unpacked GROUP BY plan, CASE WHEN lowest_price >= 28 THEN 'PREMIUM' ELSE 'STANDARD' END;
